transform.program:
# join.star -- deterministic join of API page metadata (list_pages roster +
# get_page canonical record) with browser-sourced (or lease-fallback) view
# analytics for ONE focus page, plus threshold classification.
#
# Predeclared params: pages, target, analytics, reasoned, drift, drift_reason,
# stale_before, high_traffic_view_threshold, max_space_pages, page_id.
# Output via `result`. Pure transform: zero builtins, no I/O possible.
#
# DECISION (see README "your call" section): sibling pages returned by
# list_pages but never visited by the browser step are classified
# unchecked_no_analytics, NEVER zero_view. zero_view is a positive claim this
# primitive can only make after actually reading a page's Analytics panel (or
# its lease fallback); a page we simply didn't check gets no view-based verdict
# at all, fabricated or otherwise.

def _date_only(d):
    # Starlark has no datetime; accept an ISO yyyy-mm-dd prefix, else None.
    if d == None or type(d) != "string" or len(d) < 10:
        return None
    y, m, day = d[0:4], d[5:7], d[8:10]
    if y.isdigit() and m.isdigit() and day.isdigit() and d[4] == "-" and d[7] == "-":
        return d[0:10]
    return None

def _int_or_none(v):
    if type(v) == "int":
        return v
    return None

def _threshold():
    # Optional-with-default input: the offline test harness does not fill
    # workflow-level `default:` values for cases that supply a partial
    # `input:` block, so this transform must not assume it is ever non-null.
    if high_traffic_view_threshold == None:
        return 100
    return high_traffic_view_threshold

def _cap():
    if max_space_pages == None:
        return 50
    return max_space_pages

def _view_count():
    if drift:
        if reasoned == None:
            return None
        return _int_or_none(reasoned.get("view_count"))
    if analytics == None:
        return None
    return _int_or_none(analytics.get("view_count"))

def _viewers():
    if drift:
        if reasoned == None:
            return None
        return _int_or_none(reasoned.get("viewers"))
    if analytics == None:
        return None
    return _int_or_none(analytics.get("viewers"))

def _classify(view_count, created_at):
    if view_count == None:
        return "unchecked_no_analytics"
    if view_count == 0:
        return "zero_view"
    cutoff = _date_only(stale_before)
    created = _date_only(created_at)
    if created != None and cutoff != None and created < cutoff and view_count >= _threshold():
        return "stale_high_traffic"
    return "healthy"

focus_id = target.get("id") if target != None else page_id

# Locate the focus page within the roster (for created_at) and split the
# remaining roster into siblings -- the join key is page_id, matched against
# the FULL concatenated roster regardless of how many cursor pages it took to
# fetch it (paginate: all already flattens `pages:` fixtures into one items
# list before this transform runs).
focus_created_at = None
siblings = []
for p in (pages or []):
    if p.get("id") == focus_id:
        focus_created_at = p.get("created_at")
    else:
        siblings.append(p)

view_count = _view_count()
viewers = _viewers()
classification = _classify(view_count, focus_created_at)

focus_page = {
    "page_id": focus_id,
    "title": target.get("title") if target != None else None,
    "url": target.get("url") if target != None else None,
    "status": target.get("status") if target != None else None,
    "version": target.get("version") if target != None else None,
    "created_at": focus_created_at,
    "view_count": view_count,
    "viewers": viewers,
    "classification": classification,
    "analytics_source": "reasoning_fallback" if drift else "cached_selectors",
}

capped_siblings = siblings[:_cap()]
space_pages = []
for p in capped_siblings:
    space_pages.append({
        "page_id": p.get("id"),
        "title": p.get("title"),
        "url": p.get("url"),
        "status": p.get("status"),
        "version": p.get("version"),
        "created_at": p.get("created_at"),
        "classification": "unchecked_no_analytics",
    })

all_classes = [classification] + [sp["classification"] for sp in space_pages]

def _count(label):
    n = 0
    for c in all_classes:
        if c == label:
            n += 1
    return n

result = {
    "focus_page": focus_page,
    "space_pages": space_pages,
    "extraction": {
        "mode": "reasoning_fallback" if drift else "cached_selectors",
        "drift_detected": drift,
        "drift_reason": drift_reason if drift else None,
        "repair_proposed": drift,     # drift always opens a repair proposal (03 §6)
    },
    "summary": {
        "space_page_count": len(pages or []),
        "space_pages_returned": len(space_pages),
        "classification_counts": {
            "stale_high_traffic": _count("stale_high_traffic"),
            "zero_view": _count("zero_view"),
            "healthy": _count("healthy"),
            "unchecked_no_analytics": _count("unchecked_no_analytics"),
        },
    },
}
